package crypto

import (
    "crypto/md5"
    "crypto/sha1"
    "encoding/hex"
    "math/rand"
)

func HashPasswordMD5(password string) string {
    h := md5.Sum([]byte(password))
    return hex.EncodeToString(h[:])
}

func HashDataSHA1(data string) string {
    h := sha1.Sum([]byte(data))
    return hex.EncodeToString(h[:])
}

func GenerateNonce() int {
    return rand.Intn(999999)
}
